import * as fs from "fs";

const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

const n = Number(input[0]);
const intervals = input.slice(1, n + 1).map((l) => l.split(" ").map(Number));

// 終了時刻の早い順に見て、選べるものは選ぶ
intervals.sort((p, q) => p[1] - q[1]);
let count = 0;
let lastEnd = -Infinity;
for (const [s, t] of intervals) {
  if (s >= lastEnd) {
    count++;
    lastEnd = t;
  }
}
console.log(count);
